<?php require __DIR__.'/bootstrap.php';require_login();require __DIR__.'/movidesk.php';require __DIR__.'/portal-data.php';$u=$_SESSION['user'];$isAdmin=$u['role']==='admin';if($isAdmin){$companyId=max(1,(int)($_GET['company_id']??0));if(!$companyId){http_response_code(400);exit('Informe a empresa (parâmetro company_id).');}}elseif($u['role']==='client'&&$u['company_id']){$companyId=(int)$u['company_id'];}else{http_response_code(403);exit('Relatório disponível somente para clientes vinculados ou administradores.');}$st=$pdo->prepare('SELECT * FROM companies WHERE id=? AND status=\'active\'');$st->execute([$companyId]);$company=$st->fetch();$st=$pdo->prepare("SELECT * FROM contracts WHERE company_id=? AND status='active' ORDER BY id DESC LIMIT 1");$st->execute([$companyId]);$contract=$st->fetch();if(!$company||!$contract){http_response_code(404);exit('Contrato não encontrado.');}$month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??'')?$_GET['month']:date('Y-m');$error='';$usage=['raw'=>[],'appointments'=>[],'consumed'=>0.0,'definition'=>[]];$periodClosed=false;try{$usage=portal_consumption($contract['name'],$month);}catch(Throwable $e){error_log('Newsiga report Movidesk: '.$e->getMessage());$error='Não foi possível carregar os dados deste relatório.';}$periodClosed=portal_period_is_closed($usage['raw']);$contracted=(float)($usage['raw']['contractedHours']??$contract['monthly_hours']);$consumed=$usage['consumed'];$available=max(0,$contracted-$consumed);$extra=max(0,$consumed-$contracted);$tickets=portal_group_tickets($usage['appointments']);$baseRate=(float)$contract['base_amount'];$excessRate=(float)$contract['excess_hour_amount'];$differentiated=(bool)($usage['definition']['differentiateHoursFranchise']??false)&&!empty($usage['definition']['typeActivities']);$rules=[];$typeTotals=[];if($differentiated){[$tickets,$grandTotal,$rules,$typeTotals]=portal_differentiated_values($tickets,$usage['definition']);$baseTotal=0.0;$extraTotal=0.0;}else{[$tickets,$extraTotal]=portal_ticket_values($tickets,$contracted,$baseRate,$excessRate);$baseTotal=$contracted*$baseRate;if(portal_has_minimum_package((string)($company['slug']??''))&&(float)($usage['raw']['exceededHourAmount']??0)>0)$extraTotal=(float)$usage['raw']['exceededHourAmount'];$grandTotal=$baseTotal+$extraTotal;}if(portal_bills_by_consumption((string)($company['slug']??''))&&!$differentiated){$baseTotal=0.0;$extraTotal=0.0;foreach($tickets as $ticket){$baseTotal+=((float)($ticket['covered_hours']??0))*$baseRate;$extraTotal+=((float)($ticket['extra_hours']??0))*$excessRate;}$baseTotal=round($baseTotal,2);$extraTotal=round($extraTotal,2);$grandTotal=$baseTotal+$extraTotal;}$percent=$contracted>0?min(100,($consumed/$contracted)*100):0;function report_date(string $date):string{$timestamp=strtotime($date);return$timestamp?date('d/m/Y',$timestamp):$date;}if($differentiated){$rows='';foreach($typeTotals as $type=>$value){if(abs($value)<0.005)continue;$rate=(float)($rules[$type]['rate']??0);$rows.='<div><span>'.e($type).' <small class="unit-rate">R$ '.number_format($rate,2,',','.').'/h</small></span><strong>R$ '.number_format($value,2,',','.').'</strong></div>';}$replacement='<div class="totals">'.$rows.'<div class="grand"><span>Total do período</span><strong>R$ '.number_format($grandTotal,2,',','.').'</strong></div></div>';ob_start(static function(string $html)use($replacement):string{return preg_replace('~<div class="totals">.*?<div class="grand">.*?</div></div>~s',$replacement,$html,1)??$html;});}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Relatório <?=e($company['name'])?> · <?=e(portal_month_label($month))?></title><style>:root{--ink:#102a24;--muted:#65766f;--green:#2a9d78;--paper:#f4f5f2;--line:#dde2de}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,sans-serif}.toolbar{position:sticky;top:0;display:flex;justify-content:flex-end;gap:10px;padding:14px 5vw;background:#102a24}.toolbar a,.toolbar button{padding:11px 15px;border:1px solid #ffffff55;background:transparent;color:#fff;font-weight:700;text-decoration:none;cursor:pointer}.toolbar button{background:#fff;color:#102a24}.toolbar-period{display:flex;gap:8px;margin-right:auto}.toolbar-period input{padding:0 10px;border:1px solid #ffffff55;background:transparent;color:#fff;font-weight:700;border-radius:3px}.toolbar-period input::-webkit-calendar-picker-indicator{filter:invert(1);cursor:pointer}.toolbar-period button{border:1px solid #ffffff55;background:transparent;color:#fff;font-weight:700;padding:0 15px;cursor:pointer}.report{width:min(980px,calc(100% - 32px));margin:28px auto;background:#fff;padding:44px}.brand{font-size:28px;font-weight:800;letter-spacing:-2px}.brand span{color:#69bd45}.hero{margin:30px 0;padding:28px;background:#151917;color:#fff}.kicker{font-size:10px;letter-spacing:.16em;font-weight:800;color:#8fdcc5}.hero h1{margin:9px 0;font-size:30px}.hero p{margin:0;color:#aab5b0}.period-state{display:inline-block;margin:-18px 0 20px;padding:6px 9px;background:#fff6dc;color:#705711;font-size:10px;font-weight:700}.period-state.closed{background:#e4f4de;color:#28652d}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{padding:18px;border:1px solid var(--line)}.metric small{display:block;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.07em;margin-bottom:11px}.metric strong{font-size:21px}.section{margin-top:32px}.section h2{font-size:13px;letter-spacing:.12em}.progress-row{display:flex;justify-content:space-between;font-size:13px}.track{height:7px;background:#e2e8e4;margin:10px 0}.fill{height:100%;background:var(--green)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:12px 9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted);font-size:10px;letter-spacing:.06em}.money{text-align:right;white-space:nowrap}.totals{width:min(430px,100%);margin:25px 0 0 auto}.totals div{display:flex;justify-content:space-between;align-items:baseline;gap:18px;padding:8px 0;border-bottom:1px solid var(--line)}.unit-rate{margin-left:6px;color:#89968f;font-size:10px;font-weight:400;white-space:nowrap}.totals .grand{font-size:18px;font-weight:800;border-bottom:0}@media(max-width:700px){.report{padding:25px}.metrics{grid-template-columns:1fr 1fr}.table-wrap{overflow:auto}}@media print{body{background:#fff}.toolbar{display:none}.report{width:100%;margin:0;padding:15mm;box-shadow:none}.hero{-webkit-print-color-adjust:exact;print-color-adjust:exact}.fill{-webkit-print-color-adjust:exact;print-color-adjust:exact}@page{size:A4;margin:0}}</style></head><body><nav class="toolbar"><form method="get" class="toolbar-period"><?php if($isAdmin):?><input type="hidden" name="company_id" value="<?=(int)$companyId?>"><?php endif;?><input type="month" name="month" value="<?=e($month)?>" required><button type="submit">Ver período</button></form><a href="<?=$isAdmin?url('admin/'):url('dashboard.php?month='.urlencode($month))?>"><?=$isAdmin?'Voltar à administração':'Voltar ao painel'?></a><button onclick="window.print()">Imprimir / salvar PDF</button></nav><main class="report"><div class="brand">newsiga</div><header class="hero"><span class="kicker">RELATÓRIO EXECUTIVO DE ATENDIMENTOS</span><h1><?=e($company['name'])?></h1><p>Competência: <?=e(portal_month_label($month))?> · <?=e($contract['name'])?></p></header><p class="period-state <?=$periodClosed?'closed':''?>"><?=$periodClosed?'Fechamento oficial':'Prévia do período'?></p><?php if($error):?><p style="color:#9b342b"><?=e($error)?></p><?php else:?><section class="metrics"><article class="metric"><small>HORAS CONSUMIDAS</small><strong><?=portal_duration($consumed)?></strong></article><article class="metric"><small>HORAS DISPONÍVEIS</small><strong><?=portal_duration($available)?></strong></article><article class="metric"><small>PACOTE CONTRATADO</small><strong><?=portal_duration($contracted)?></strong></article><article class="metric"><small>VALOR DO PERÍODO</small><strong>R$ <?=number_format($grandTotal,2,',','.')?></strong></article></section><section class="section"><h2>CONSUMO CONTRATUAL</h2><div class="progress-row"><span>Utilizado: <?=portal_duration($consumed)?> de <?=portal_duration($contracted)?></span><strong><?=number_format($percent,0,',','.')?>%</strong></div><div class="track"><div class="fill" style="width:<?=$percent?>%"></div></div><span style="font-size:12px"><?=($extra>0)?portal_duration($extra).' excedentes no período':portal_duration($available).' restantes no período'?></span></section><section class="section"><h2>DISTRIBUIÇÃO DOS ATENDIMENTOS</h2><div class="table-wrap"><table><thead><tr><th>TICKET</th><th>DATA</th><th>ATIVIDADE</th><th>HORAS</th><th class="money">VALOR</th></tr></thead><tbody><?php foreach($tickets as $ticket):?><tr><td><strong>#<?=e($ticket['number'])?></strong></td><td><?=e(report_date($ticket['date']))?></td><td><?=e($ticket['activity'])?><br><span style="color:#65766f"><?=e(implode(', ',array_keys($ticket['responsibles'])))?></span></td><td><?=portal_duration($ticket['hours'])?></td><td class="money">R$ <?=number_format($ticket['value'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$tickets):?><tr><td colspan="5">Nenhum atendimento no período.</td></tr><?php endif;?></tbody></table></div><div class="totals"><div><span>Valor-base <small class="unit-rate">R$ <?=number_format($baseRate,2,',','.')?>/h</small></span><strong>R$ <?=number_format($baseTotal,2,',','.')?></strong></div><div><span>Horas excedentes <small class="unit-rate">R$ <?=number_format($excessRate,2,',','.')?>/h</small></span><strong>R$ <?=number_format($extraTotal,2,',','.')?></strong></div><div class="grand"><span>Total do período</span><strong>R$ <?=number_format($grandTotal,2,',','.')?></strong></div></div></section><?php endif;?></main></body></html>
